#!/usr/bin/env python3
"""Export actual native technology data with stable-lane annotations. Never runs the game."""
from pathlib import Path
import json
M=Path(__file__).resolve().parents[1]
D=json.loads((M/'design/设计数据.json').read_text())
columns=json.loads((M/'jsons/Techs.json').read_text())
zh=dict(l.split(' = ',1) for l in (M/'jsons/translations/Simplified_Chinese.properties').read_text().splitlines() if ' = ' in l)
data=[dict(id=t['name'],name=zh[t['name']],cost=t['cost'],col=c['columnNumber'],row=t['row'],era=c['era'],parents=t['prerequisites'],unlocks=D['techs'][t['name']][5]) for c in columns for t in c['techs']]
html=r"""<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FantasyUnciv · 科技路线</title>
<style>*{box-sizing:border-box}body{margin:0;background:#101820;color:#e9eef3;font:14px system-ui}header{padding:14px 20px;border-bottom:1px solid #3b5060;background:#17232d}h1{margin:0 0 6px;font-size:21px}p{margin:5px 0;color:#b4c7d4;line-height:1.5}button,input,select{font:inherit;border:1px solid #516574;border-radius:6px;padding:7px;background:#233442;color:#e7eef4}button{cursor:pointer}button:hover{background:#385467}.controls{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:10px}#detail{min-height:42px;margin-top:9px;max-width:1400px;line-height:1.5}#view{height:calc(100vh - 222px);min-height:320px;overflow:auto}svg{display:block}.edge{fill:none;stroke:#7b919f;stroke-width:1.5;opacity:.72}.edge.active{stroke:#ffe297;stroke-width:2.8;opacity:1}.edge.dim{opacity:.06}.node{cursor:pointer}.node.dim{opacity:.1}.node.active rect{stroke:#ffe297;stroke-width:2.5}.node text{pointer-events:none}.lane{font-size:14px;fill:#a8becb}.name{font-size:16px;fill:#edf4f8}.meta{font-size:11px;fill:#beced9}.unlock{font-size:11px;fill:#cddbc8}#zoom{width:110px}</style>
<header><h1>FantasyUnciv · COUNT 科技 / EDGES 条 AND 前置 · 0.13.0</h1><p>实际MOD数据预览，非实机画面。共享基础、阶段推进、应用汇合；路线聚焦与辅助着色仅用于此预览。五项初始研究均35科研，开拓者无科技要求，不统一赠送农业。</p>
<div class="controls"><button id="all">显示全部</button><button id="fit">整树总览</button><button id="opening">精神路线</button><select id="branch"><option value="">聚焦路线…</option></select><input id="find" placeholder="科技名称或ID"><label>缩放 <input id="zoom" type="range" min="25" max="100" value="60"></label></div><div id="detail">单击科技：高亮它的全部AND前置，并显示实际解锁。仍保留有用途的跨分支联系。</div></header><div id="view"><div id="canvas"></div></div>
<script>
const data=DATA,lanes=LANES,tracks=TRACKS,byId=Object.fromEntries(data.map(t=>[t.id,t])),ns='http://www.w3.org/2000/svg';
const W=240+(Math.max(...data.map(t=>t.col))+1)*260,H=115+Math.max(...data.map(t=>t.row))*94;
function el(n,a,text){const e=document.createElementNS(ns,n);for(const[k,v]of Object.entries(a||{}))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e}
const svg=el('svg',{width:W,height:H,viewBox:`0 0 ${W} ${H}`});document.getElementById('canvas').appendChild(svg);const nodes=[],edges=[];const pos=t=>({x:205+t.col*260,y:78+(t.row-1)*94});
const colors={1:'#504365',2:'#645337',3:'#394c60',4:'#4c5736',5:'#354e5d',6:'#31566a',7:'#31566a',8:'#564264',9:'#3e4d73',10:'#59465e',11:'#3e6252',12:'#695242',13:'#466036',14:'#466036',15:'#654544',16:'#63533c',17:'#63533c',18:'#35576d',19:'#35576d'};
for(const [row,label]of Object.entries(lanes)){const y=78+(Number(row)-1)*94;svg.appendChild(el('rect',{x:0,y:y-7,width:W,height:86,fill:Number(row)%2?'#15212b':'#101c25'}));svg.appendChild(el('text',{x:14,y:y+38,class:'lane'},label))}
for(const c of [...new Set(data.map(t=>t.col))].sort((a,b)=>a-b)){const x=205+c*260;svg.appendChild(el('line',{x1:x-20,y1:47,x2:x-20,y2:H-24,stroke:'#2c3e4b'}));svg.appendChild(el('text',{x,y:29,fill:'#b1c7d5','font-size':15},`${data.find(t=>t.col===c).era} · 列${c}`))}
for(const t of data){const b=pos(t);for(const p of t.parents){const a=pos(byId[p]),mx=(a.x+210+b.x)/2,e=el('path',{d:`M${a.x+210},${a.y+36} H${mx} V${b.y+36} H${b.x}`,class:'edge'});svg.appendChild(e);edges.push({e,from:p,to:t.id})}}
for(const t of data){const p=pos(t),g=el('g',{class:'node',transform:`translate(${p.x},${p.y})`});g.appendChild(el('title',{},`${t.name}\n${t.unlocks}`));g.appendChild(el('rect',{width:210,height:72,rx:8,fill:colors[Math.ceil(t.col/2)+1],stroke:'#7993a2','stroke-width':1.3}));g.appendChild(el('text',{x:11,y:24,class:'name'},t.name));g.appendChild(el('text',{x:11,y:44,class:'meta'},`${t.id} · ${t.cost}科研`));const summary=t.unlocks.split('；').slice(0,2).join(' · ');g.appendChild(el('text',{x:11,y:61,class:'unlock'},summary.length>23?summary.slice(0,22)+'…':summary));g.onclick=()=>select(t.id);svg.appendChild(g);nodes.push({id:t.id,g})}
function ancestors(id,set=new Set()){if(set.has(id))return set;set.add(id);byId[id].parents.forEach(p=>ancestors(p,set));return set}
function mark(set){nodes.forEach(n=>n.g.setAttribute('class','node '+(set.has(n.id)?'active':'dim')));edges.forEach(e=>e.e.setAttribute('class','edge '+(set.has(e.from)&&set.has(e.to)?'active':'dim')))}
function select(id){const t=byId[id],set=ancestors(id);mark(set);document.getElementById('detail').textContent=`${t.name}：直接前置 ${t.parents.map(p=>byId[p].name).join('、')||'无'}。含自身${set.size}项 / ${[...set].reduce((n,k)=>n+byId[k].cost,0)}基础科研。实际解锁/效果：${t.unlocks}。`}
const branch=document.getElementById('branch');for(const label of Object.keys(tracks)){const o=document.createElement('option');o.value=label;o.textContent=label;branch.appendChild(o)}branch.onchange=()=>{if(!branch.value)return reset();const set=new Set();tracks[branch.value].forEach(n=>ancestors('D01-T'+String(n).padStart(2,'0'),set));mark(set);document.getElementById('detail').textContent=`${branch.value}：高亮路线及其全部必修前置。交叉处只有箭头两端表示研究条件。`};
function reset(){nodes.forEach(n=>n.g.setAttribute('class','node'));edges.forEach(e=>e.e.setAttribute('class','edge'));branch.value='';document.getElementById('find').value='';document.getElementById('detail').textContent='单击科技追踪实际解锁与全部AND前置。界面交点不表示额外研究条件。'}document.getElementById('all').onclick=reset;
function zoom(){const z=Number(document.getElementById('zoom').value)/100;svg.style.width=W*z+'px';svg.style.height=H*z+'px'}document.getElementById('zoom').oninput=zoom;document.getElementById('fit').onclick=()=>{reset();document.getElementById('zoom').value=Math.max(25,Math.min(100,(window.innerWidth-22)*100/W));zoom()};document.getElementById('opening').onclick=()=>{select('D01-T53');nodes.find(n=>n.id==='D01-T53').g.scrollIntoView({block:'center',inline:'center'})};document.getElementById('find').oninput=e=>{const q=e.target.value.toLowerCase();if(!q)return reset();const t=data.find(t=>t.name.includes(q)||t.id.toLowerCase().includes(q));if(t){select(t.id);nodes.find(n=>n.id===t.id).g.scrollIntoView({block:'center',inline:'center'})}};zoom();
</script></html>"""
html=html.replace('COUNT',str(len(data))).replace('EDGES',str(sum(len(t['parents']) for t in data))).replace('DATA',json.dumps(data,ensure_ascii=False).replace('</','<\\/')).replace('LANES',json.dumps(D['layout_lanes'],ensure_ascii=False)).replace('TRACKS',json.dumps(D['technology_tracks'],ensure_ascii=False))
html=html.replace(' · 0.13.0',' · '+json.loads((M/'design/provenance.json').read_text())['mod_version'])
output=M/'build';output.mkdir(parents=True,exist_ok=True);(output/'tech-tree.html').write_text(html)
print('Exported',len(data),'nodes and',sum(len(t['parents']) for t in data),'edges.')
